    \draw[->, thick, orange] (0,0) -- ({3 / sqrt(10)},{1 / sqrt(10)}) node[midway, below] {$\vec{q}_1$};
    \draw[->, thick, yellow] (0,0) -- ({-sqrt(10) / 10},{3 * sqrt(10) / 10}) node[midway, left] {$\vec{q}_2$};
    \draw[->, thick, pink] (0,0) -- (-3/8,-1/8) node[midway, above left]{};
