>\node[nodestyle, name=A] {A}
>  child { node[nodestyle, name=B] {B}
>    child { node[nodestyle, name=D] {D} }
>    child { node[nodestyle, name=E] {E} }
>  }
>  child { node[nodestyle, name=C] {C}
