>    \draw (0,-3.05) -- (10,-3.05);
>    \draw (0,-7.05) -- (10,-7.05);
>    \draw (0,-7.15) -- (10,-7.15);
>
>
>    % Left column text
>    \node[anchor=west] at (0.2,0.2) {\textbf{NET SALES}};
